import urllib.request, json, base64, io
import numpy as np
from PIL import Image

def get_render(view='iso', width=640, height=480):
    req = urllib.request.Request(
        'http://loophole-sim:8000/mcp',
        data=json.dumps({
            'jsonrpc': '2.0',
            'id': 1,
            'method': 'tools/call',
            'params': {
                'name': 'render',
                'arguments': {
                    'view': view,
                    'modalities': ['rgb', 'depth', 'segmentation'],
                    'depth_format': 'metric',
                    'width': width,
                    'height': height
                }
            }
        }).encode(),
        headers={'Content-Type': 'application/json', 'Accept': 'application/json'}
    )
    with urllib.request.urlopen(req, timeout=10) as resp:
        res = json.loads(resp.read().decode())

    images = []
    caption = None
    for item in res['result']['content']:
        if item.get('type') == 'image':
            images.append(Image.open(io.BytesIO(base64.b64decode(item['data']))))
        elif item.get('type') == 'text':
            caption = json.loads(item['text'])
    return images, caption

images, caption = get_render('iso')
depth = np.array(images[1], dtype=np.float32) / 1000.0 # depth in metres
seg = np.array(images[2]) # RGB

# Let's inspect unique colors in seg
colors, counts = np.unique(seg.reshape(-1, 3), axis=0, return_counts=True)
for c, cnt in zip(colors, counts):
    print(f'Color: {c}, count: {cnt}')
"

