python3 -c "
import numpy as np
from scipy.spatial.transform import Rotation

data = np.load('/app/solid_sdf_a.npz')
dist_field = data['dist']
bmin = data['bmin']
res = float(data['res'])
shape = np.array(dist_field.shape)
sample_b_local = np.load('/app/sample_b_local.npy')

def check_pose(pos, rot_mat, safety_margin=0.005):
    pts = sample_b_local @ rot_mat.T + pos
    coords = np.floor((pts - bmin) / res).astype(int)
    in_box = (coords[:, 0] >= 0) & (coords[:, 0] < shape[0]) & \
             (coords[:, 1] >= 0) & (coords[:, 1] < shape[1]) & \
             (coords[:, 2] >= 0) & (coords[:, 2] < shape[2])
    if np.any(in_box):
        dists = dist_field[coords[in_box, 0], coords[in_box, 1], coords[in_box, 2]]
        if np.any(dists <= safety_margin):
            return False
        return True
    return True

def can_slide_to_infinity(pos, rot_mat):
    dirs = []
    for x in [-1, 0, 1]:
        for y in [-1, 0, 1]:
            for z in [-1, 0, 1]:
                if x == 0 and y == 0 and z == 0:
                    continue
                v = np.array([x, y, z], dtype=float)
                dirs.append(v / np.linalg.norm(v))
    for v in dirs:
        collided = False
        for t in np.arange(0.04, 3.0, 0.05):
            if not check_pose(pos + t * v, rot_mat):
                collided = True
                break
        if not collided:
            return True, v
    return False, None

# Test poses with y > 1.5 (above Leg A2) or x > 2.0 or z > 1.0
print('Testing poses...')
for dy in np.arange(0.5, 2.0, 0.2):
    for dz in np.arange(-0.5, 1.5, 0.2):
        for dx in np.arange(-0.5, 1.5, 0.2):
            pos = np.array([1.2 + dx, 0.36 + dy, 0.28 + dz])
            R = np.eye(3)
            if check_pose(pos, R):
                free, d = can_slide_to_infinity(pos, R)
                if free:
                    print(f'Found separated pose: pos={pos}, dir={d}')
                    break
        else:
            continue
        break
    else:
        continue
    break
"

python3 -c "
cpp_code = '''#include <iostream>
#include <vector>
#include <cmath>
#include <chrono>
#include <cstdio>
#include <cstdlib>

struct Vec3 {
    float x, y, z;
};

struct Mat3 {
    float m[3][3];
    Vec3 mul(const Vec3& v) const {
        return {
            m[0][0]*v.x + m[0][1]*v.y + m[0][2]*v.z,
            m[1][0]*v.x + m[1][1]*v.y + m[1][2]*v.z,
            m[2][0]*v.x + m[2][1]*v.y + m[2][2]*v.z
        };
    }
};

Mat3 euler_to_mat(float roll, float pitch, float yaw) {
    float cr = cosf(roll), sr = sinf(roll);
    float cp = cosf(pitch), sp = sinf(pitch);
    float cy = cosf(yaw), sy = sinf(yaw);
    Mat3 R;
    R.m[0][0] = cy * cp;
    R.m[0][1] = cy * sp * sr - sy * cr;
    R.m[0][2] = cy * sp * cr + sy * sr;
    R.m[1][0] = sy * cp;
    R.m[1][1] = sy * sp * sr + cy * cr;
    R.m[1][2] = sy * sp * cr - cy * sr;
    R.m[2][0] = -sp;
    R.m[2][1] = cp * sr;
    R.m[2][2] = cp * cr;
    return R;
}

int main() {
    FILE* f_hdr = fopen(\"/app/sdf_header.bin\", \"rb\");
    int shape[3];
    Vec3 bmin;
    float res;
    fread(shape, sizeof(int), 3, f_hdr);
    fread(&bmin, sizeof(float), 3, f_hdr);
    fread(&res, sizeof(float), 1, f_hdr);
    fclose(f_hdr);

    int total_voxels = shape[0] * shape[1] * shape[2];
    std::vector<float> dist_field(total_voxels);
    FILE* f_df = fopen(\"/app/dist_field.raw\", \"rb\");
    fread(dist_field.data(), sizeof(float), total_voxels, f_df);
    fclose(f_df);

    std::vector<Vec3> sample_b(3000);
    FILE* f_sb = fopen(\"/app/sample_b.raw\", \"rb\");
    fread(sample_b.data(), sizeof(float), 3000 * 3, f_sb);
    fclose(f_sb);

    auto check_pose = [&](Vec3 pos, Mat3 R, float margin) -> float {
        float min_d = 1e9f;
        int s0 = shape[0], s1 = shape[1], s2 = shape[2];
        float inv_res = 1.0f / res;
        for (const auto& pt : sample_b) {
            Vec3 p = R.mul(pt);
            p.x += pos.x; p.y += pos.y; p.z += pos.z;
            int ix = (int)((p.x - bmin.x) * inv_res);
            int iy = (int)((p.y - bmin.y) * inv_res);
            int iz = (int)((p.z - bmin.z) * inv_res);
            if (ix >= 0 && ix < s0 && iy >= 0 && iy < s1 && iz >= 0 && iz < s2) {
                float d = dist_field[(ix * s1 + iy) * s2 + iz];
                if (d < min_d) {
                    min_d = d;
                    if (d <= margin) return d;
                }
            }
        }
        return min_d;
    };

    Vec3 p0 = {1.2f, 0.36f, 0.28f};
    Mat3 R0 = euler_to_mat(0, 0, 0);
    float d0 = check_pose(p0, R0, 0.005f);
    std::cout << \"Initial clearance in C++: \" << d0 << std::endl;

    auto t0 = std::chrono::high_resolution_clock::now();
    int N = 100000;
    for (int i = 0; i < N; ++i) {
        Vec3 p = {p0.x + 0.001f * (i % 10), p0.y, p0.z};
        check_pose(p, R0, 0.005f);
    }
    auto t1 = std::chrono::high_resolution_clock::now();
    double dt = std::chrono::duration<double>(t1 - t0).count();
    std::cout << N << \" checks in \" << dt << \" s (\" << (N / dt) << \" checks/sec)\" << std::endl;

    return 0;
}
'''
with open('/app/bench.cpp', 'w') as f:
    f.write(cpp_code)
