#include <iostream>
#include <vector>
#include <cmath>
#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <random>
#include <algorithm>

struct Vec3 { float x, y, z; };

struct Quat {
    float w, x, y, z;
    static Quat identity() { return {1, 0, 0, 0}; }
    float dot(const Quat& o) const { return w*o.w + x*o.x + y*o.y + z*o.z; }
    void normalize() {
        float l = sqrtf(dot(*this));
        if (l > 1e-6f) { w /= l; x /= l; y /= l; z /= l; }
    }
};

struct Mat3 {
    float m[3][3];
    Vec3 mul(const Vec3& v) const {
        return {
            m[0][0]*v.x + m[0][1]*v.y + m[0][2]*v.z,
            m[1][0]*v.x + m[1][1]*v.y + m[1][2]*v.z,
            m[2][0]*v.x + m[2][1]*v.y + m[2][2]*v.z
        };
    }
};

Mat3 quat_to_mat(const Quat& q) {
    Mat3 R;
    float w = q.w, x = q.x, y = q.y, z = q.z;
    R.m[0][0] = 1.0f - 2.0f*(y*y + z*z);
    R.m[0][1] = 2.0f*(x*y - w*z);
    R.m[0][2] = 2.0f*(x*z + w*y);
    R.m[1][0] = 2.0f*(x*y + w*z);
    R.m[1][1] = 1.0f - 2.0f*(x*x + z*z);
    R.m[1][2] = 2.0f*(y*z - w*x);
    R.m[2][0] = 2.0f*(x*z - w*y);
    R.m[2][1] = 2.0f*(y*z + w*x);
    R.m[2][2] = 1.0f - 2.0f*(x*x + y*y);
    return R;
}

Quat slerp(Quat q0, Quat q1, float t) {
    float d = q0.dot(q1);
    if (d < 0.0f) {
        q1 = {-q1.w, -q1.x, -q1.y, -q1.z};
        d = -d;
    }
    if (d > 0.9995f) {
        Quat res = {
            q0.w + t*(q1.w - q0.w),
            q0.x + t*(q1.x - q0.x),
            q0.y + t*(q1.y - q0.y),
            q0.z + t*(q1.z - q0.z)
        };
        res.normalize();
        return res;
    }
    float theta_0 = acosf(d);
    float theta = theta_0 * t;
    float sin_theta = sinf(theta);
    float sin_theta_0 = sinf(theta_0);
    float s0 = cosf(theta) - d * sin_theta / sin_theta_0;
    float s1 = sin_theta / sin_theta_0;
    return {
        s0*q0.w + s1*q1.w,
        s0*q0.x + s1*q1.x,
        s0*q0.y + s1*q1.y,
        s0*q0.z + s1*q1.z
    };
}

int shape[3];
Vec3 bmin;
float res;
std::vector<float> dist_field;
std::vector<Vec3> sample_b;

bool check_pose_fast(const Vec3& pos, const Mat3& R, float margin) {
    int s0 = shape[0], s1 = shape[1], s2 = shape[2];
    float inv_res = 1.0f / res;
    // Step by 3 for initial prune
    for (size_t i = 0; i < sample_b.size(); i += 3) {
        Vec3 p = R.mul(sample_b[i]);
        p.x += pos.x; p.y += pos.y; p.z += pos.z;
        int ix = (int)((p.x - bmin.x) * inv_res);
        int iy = (int)((p.y - bmin.y) * inv_res);
        int iz = (int)((p.z - bmin.z) * inv_res);
        if (ix >= 0 && ix < s0 && iy >= 0 && iy < s1 && iz >= 0 && iz < s2) {
            if (dist_field[(ix * s1 + iy) * s2 + iz] <= margin) return false;
        }
    }
    for (size_t i = 0; i < sample_b.size(); ++i) {
        if (i % 3 == 0) continue;
        Vec3 p = R.mul(sample_b[i]);
        p.x += pos.x; p.y += pos.y; p.z += pos.z;
        int ix = (int)((p.x - bmin.x) * inv_res);
        int iy = (int)((p.y - bmin.y) * inv_res);
        int iz = (int)((p.z - bmin.z) * inv_res);
        if (ix >= 0 && ix < s0 && iy >= 0 && iy < s1 && iz >= 0 && iz < s2) {
            if (dist_field[(ix * s1 + iy) * s2 + iz] <= margin) return false;
        }
    }
    return true;
}

struct Node {
    Vec3 pos;
    Quat q;
    Mat3 R;
    int parent;
};

struct Tree {
    std::vector<Node> nodes;
    int nearest(const Vec3& p, const Quat& q) const {
        float min_d = 1e9f;
        int best_idx = 0;
        for (int i = 0; i < (int)nodes.size(); ++i) {
            const auto& n = nodes[i];
            float dx = n.pos.x - p.x, dy = n.pos.y - p.y, dz = n.pos.z - p.z;
            float pos_dist2 = dx*dx + dy*dy + dz*dz;
            float d_rot = fabsf(n.q.dot(q));
            if (d_rot > 1.0f) d_rot = 1.0f;
            float rot_angle = 2.0f * acosf(d_rot);
            float dist = pos_dist2 + 0.25f * rot_angle * rot_angle;
            if (dist < min_d) {
                min_d = dist;
                best_idx = i;
            }
        }
        return best_idx;
    }
};

enum Status { TRAPPED, ADVANCED, REACHED };

Status extend(Tree& tree, const Vec3& target_p, const Quat& target_q, int& new_idx, float max_step_p = 0.04f, float max_step_r = 0.1f) {
    int near_idx = tree.nearest(target_p, target_q);
    const Node& near_node = tree.nodes[near_idx];

    float dx = target_p.x - near_node.pos.x;
    float dy = target_p.y - near_node.pos.y;
    float dz = target_p.z - near_node.pos.z;
    float dist_p = sqrtf(dx*dx + dy*dy + dz*dz);

    float d_rot = fabsf(near_node.q.dot(target_q));
    if (d_rot > 1.0f) d_rot = 1.0f;
    float dist_r = 2.0f * acosf(d_rot);

    float frac = 1.0f;
    if (dist_p > max_step_p) frac = std::min(frac, max_step_p / dist_p);
    if (dist_r > max_step_r) frac = std::min(frac, max_step_r / dist_r);

    Vec3 step_p = {
        near_node.pos.x + frac * dx,
        near_node.pos.y + frac * dy,
        near_node.pos.z + frac * dz
    };
    Quat step_q = slerp(near_node.q, target_q, frac);
    Mat3 step_R = quat_to_mat(step_q);

    if (!check_pose_fast(step_p, step_R, 0.005f)) {
        return TRAPPED;
    }

    new_idx = (int)tree.nodes.size();
    tree.nodes.push_back({step_p, step_q, step_R, near_idx});

    if (frac >= 0.999f) return REACHED;
    return ADVANCED;
}

Status connect(Tree& tree, const Vec3& target_p, const Quat& target_q, int& final_idx) {
    Status s;
    int cur_idx = -1;
    do {
        s = extend(tree, target_p, target_q, cur_idx);
    } while (s == ADVANCED);
    final_idx = cur_idx;
    return s;
}

int main() {
    FILE* f_hdr = fopen("/app/sdf_header.bin", "rb");
    fread(shape, sizeof(int), 3, f_hdr);
    fread(&bmin, sizeof(float), 3, f_hdr);
    fread(&res, sizeof(float), 1, f_hdr);
    fclose(f_hdr);

    int total_voxels = shape[0] * shape[1] * shape[2];
    dist_field.resize(total_voxels);
    FILE* f_df = fopen("/app/dist_field.raw", "rb");
    fread(dist_field.data(), sizeof(float), total_voxels, f_df);
    fclose(f_df);

    sample_b.resize(3000);
    FILE* f_sb = fopen("/app/sample_b.raw", "rb");
    fread(sample_b.data(), sizeof(float), 3000 * 3, f_sb);
    fclose(f_sb);

    std::cout << "Data loaded successfully!" << std::endl;

    Tree treeA, treeB;

    Vec3 p_start = {1.2f, 0.36f, 0.28f};
    Quat q_start = Quat::identity();
    treeA.nodes.push_back({p_start, q_start, quat_to_mat(q_start), -1});

    std::vector<Vec3> goal_positions = {
        {1.2f, 1.6f, 0.3f},
        {2.2f, 0.36f, 0.28f},
        {2.2f, 0.9f, 0.4f},
        {0.8f, 1.8f, 0.3f}
    };
    for (const auto& gp : goal_positions) {
        Quat gq = Quat::identity();
        treeB.nodes.push_back({gp, gq, quat_to_mat(gq), -1});
    }

    std::mt19937 rng(42);
    std::uniform_real_distribution<float> dist_x(0.5f, 2.3f);
    std::uniform_real_distribution<float> dist_y(0.0f, 1.8f);
    std::uniform_real_distribution<float> dist_z(0.0f, 0.6f);
    std::normal_distribution<float> norm_dist(0.0f, 1.0f);

    auto random_quat = [&]() -> Quat {
        Quat q = {norm_dist(rng), norm_dist(rng), norm_dist(rng), norm_dist(rng)};
        q.normalize();
        return q;
    };

    auto t0 = std::chrono::high_resolution_clock::now();
    bool connected = false;
    int conn_idx_A = -1, conn_idx_B = -1;

    std::cout << "Starting RRT-Connect..." << std::endl;

    for (int iter = 0; iter < 100000; ++iter) {
        // Sample random configuration
        Vec3 rand_p = {dist_x(rng), dist_y(rng), dist_z(rng)};
        Quat rand_q = (std::uniform_real_distribution<float>(0, 1)(rng) < 0.4f) ? Quat::identity() : random_quat();

        // Extend Tree A
        int new_A = -1;
        if (extend(treeA, rand_p, rand_q, new_A) != TRAPPED) {
            // Connect Tree B to new_A
            const auto& node_A = treeA.nodes[new_A];
            int final_B = -1;
            if (connect(treeB, node_A.pos, node_A.q, final_B) == REACHED) {
                std::cout << "TREES CONNECTED at iteration " << iter << "!" << std::endl;
                std::cout << "Tree A nodes: " << treeA.nodes.size() << ", Tree B nodes: " << treeB.nodes.size() << std::endl;
                conn_idx_A = new_A;
                conn_idx_B = final_B;
                connected = true;
                break;
            }
        }

        // Swap trees
        std::swap(treeA, treeB);

        if (iter % 2000 == 0) {
            auto t_now = std::chrono::high_resolution_clock::now();
            double el = std::chrono::duration<double>(t_now - t0).count();
            std::cout << "Iter " << iter << ": Tree A " << treeA.nodes.size() 
                      << ", Tree B " << treeB.nodes.size() 
                      << ", elapsed: " << el << "s" << std::endl;
        }
    }

    if (!connected) {
        std::cout << "Could not connect trees in iteration limit." << std::endl;
        return 1;
    }

    // Determine which tree is which
    bool A_is_start = false;
    for (const auto& n : treeA.nodes) {
        if (n.parent == -1 && fabsf(n.pos.x - p_start.x) < 1e-4f && fabsf(n.pos.y - p_start.y) < 1e-4f) {
            A_is_start = true;
            break;
        }
    }

    Tree& start_tree = A_is_start ? treeA : treeB;
    Tree& goal_tree  = A_is_start ? treeB : treeA;
    int start_conn   = A_is_start ? conn_idx_A : conn_idx_B;
    int goal_conn    = A_is_start ? conn_idx_B : conn_idx_A;

    // Trace path from start_tree
    std::vector<Node> path_start;
    int curr = start_conn;
    while (curr >= 0) {
        path_start.push_back(start_tree.nodes[curr]);
        curr = start_tree.nodes[curr].parent;
    }
    std::reverse(path_start.begin(), path_start.end());

    // Trace path from goal_tree
    std::vector<Node> path_goal;
    curr = goal_conn;
    while (curr >= 0) {
        path_goal.push_back(goal_tree.nodes[curr]);
        curr = goal_tree.nodes[curr].parent;
    }

    // Combined path
    std::vector<Node> full_path = path_start;
    for (const auto& n : path_goal) {
        full_path.push_back(n);
    }

    std::cout << "Total solution path length: " << full_path.size() << " waypoints!" << std::endl;

    FILE* f_out = fopen("/app/rrt_path.txt", "w");
    for (const auto& n : full_path) {
        fprintf(f_out, "%.5f %.5f %.5f %.5f %.5f %.5f %.5f\n",
                n.pos.x, n.pos.y, n.pos.z, n.q.w, n.q.x, n.q.y, n.q.z);
    }
    fclose(f_out);
    std::cout << "Saved path to /app/rrt_path.txt" << std::endl;

    return 0;
}

