                    R.m[0][0], R.m[0][1], R.m[0][2],
                    R.m[1][0], R.m[1][1], R.m[1][2],
                    R.m[2][0], R.m[2][1], R.m[2][2]);
        }
        fclose(f_out);
        std::cout << "Saved tail path to /app/tail_path.txt" << std::endl;
    }

    return 0;
}

