        std::vector<State> path;
        int curr = goal_idx;
        while (curr >= 0) {
            path.push_back(all_states[curr]);
            curr = all_states[curr].parent;
        }
        std::reverse(path.begin(), path.end());
        std::cout << "Solution path length: " << path.size() << " steps!" << std::endl;

        FILE* f_out = fopen("/app/solution_path.txt", "w");
        for (const auto& st : path) {
            Vec3 pos = {p0.x + st.ix * step_xyz, p0.y + st.iy * step_xyz, p0.z + st.iz * step_xyz};
            fprintf(f_out, "%.5f %.5f %.5f %.5f %.5f %.5f\n", 
                    pos.x, pos.y, pos.z,
                    st.ir * step_rot, st.ip * step_rot, st.iyw * step_rot);
        }
        fclose(f_out);
        std::cout << "Saved solution to /app/solution_path.txt" << std::endl;
    }

    return 0;
}

