#include <iostream>
#include <vector>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <algorithm>

struct Vec3 { float x, y, z; };
struct Mat3 {
    float m[3][3];
    Vec3 mul(const Vec3& v) const {
        return {
            m[0][0]*v.x + m[0][1]*v.y + m[0][2]*v.z,
            m[1][0]*v.x + m[1][1]*v.y + m[1][2]*v.z,
            m[2][0]*v.x + m[2][1]*v.y + m[2][2]*v.z
        };
    }
};

struct Quat {
    float w, x, y, z;
    float dot(const Quat& o) const { return w*o.w + x*o.x + y*o.y + z*o.z; }
    void normalize() {
        float l = sqrtf(dot(*this));
        if (l > 1e-6f) { w /= l; x /= l; y /= l; z /= l; }
    }
};

Mat3 quat_to_mat(const Quat& q) {
    Mat3 R;
    float w = q.w, x = q.x, y = q.y, z = q.z;
    R.m[0][0] = 1.0f - 2.0f*(y*y + z*z);
    R.m[0][1] = 2.0f*(x*y - w*z);
    R.m[0][2] = 2.0f*(x*z + w*y);
    R.m[1][0] = 2.0f*(x*y + w*z);
    R.m[1][1] = 1.0f - 2.0f*(x*x + z*z);
    R.m[1][2] = 2.0f*(y*z - w*x);
    R.m[2][0] = 2.0f*(x*z - w*y);
    R.m[2][1] = 2.0f*(y*z + w*x);
    R.m[2][2] = 1.0f - 2.0f*(x*x + y*y);
    return R;
}

Quat mat_to_quat(const Mat3& R) {
    Quat q;
    float tr = R.m[0][0] + R.m[1][1] + R.m[2][2];
    if (tr > 0.0f) {
        float s = 0.5f / sqrtf(tr + 1.0f);
        q.w = 0.25f / s;
        q.x = (R.m[2][1] - R.m[1][2]) * s;
        q.y = (R.m[0][2] - R.m[2][0]) * s;
        q.z = (R.m[1][0] - R.m[0][1]) * s;
    } else if ((R.m[0][0] > R.m[1][1]) && (R.m[0][0] > R.m[2][2])) {
        float s = 2.0f * sqrtf(1.0f + R.m[0][0] - R.m[1][1] - R.m[2][2]);
        q.w = (R.m[2][1] - R.m[1][2]) / s;
        q.x = 0.25f * s;
        q.y = (R.m[0][1] + R.m[1][0]) / s;
        q.z = (R.m[0][2] + R.m[2][0]) / s;
    } else if (R.m[1][1] > R.m[2][2]) {
        float s = 2.0f * sqrtf(1.0f + R.m[1][1] - R.m[0][0] - R.m[2][2]);
        q.w = (R.m[0][2] - R.m[2][0]) / s;
        q.x = (R.m[0][1] + R.m[1][0]) / s;
        q.y = 0.25f * s;
        q.z = (R.m[1][2] + R.m[2][1]) / s;
    } else {
        float s = 2.0f * sqrtf(1.0f + R.m[2][2] - R.m[0][0] - R.m[1][1]);
        q.w = (R.m[1][0] - R.m[0][1]) / s;
        q.x = (R.m[0][2] + R.m[2][0]) / s;
        q.y = (R.m[1][2] + R.m[2][1]) / s;
        q.z = 0.25f * s;
    }
    q.normalize();
    return q;
}

Quat slerp(Quat q0, Quat q1, float t) {
    float d = q0.dot(q1);
    if (d < 0.0f) {
        q1 = {-q1.w, -q1.x, -q1.y, -q1.z};
        d = -d;
    }
    if (d > 0.9995f) {
        Quat res = {
            q0.w + t*(q1.w - q0.w),
            q0.x + t*(q1.x - q0.x),
            q0.y + t*(q1.y - q0.y),
            q0.z + t*(q1.z - q0.z)
        };
        res.normalize();
        return res;
    }
    float theta_0 = acosf(d);
    float theta = theta_0 * t;
    float sin_theta = sinf(theta);
    float sin_theta_0 = sinf(theta_0);
    float s0 = cosf(theta) - d * sin_theta / sin_theta_0;
    float s1 = sin_theta / sin_theta_0;
    return {
        s0*q0.w + s1*q1.w,
        s0*q0.x + s1*q1.x,
        s0*q0.y + s1*q1.y,
        s0*q0.z + s1*q1.z
    };
}

int shape[3];
Vec3 bmin;
float res;
std::vector<float> dist_field;
std::vector<Vec3> sample_b;

bool check_pose_fast(const Vec3& pos, const Mat3& R, float margin) {
    int s0 = shape[0], s1 = shape[1], s2 = shape[2];
    float inv_res = 1.0f / res;
    for (size_t i = 0; i < sample_b.size(); i += 2) {
        Vec3 p = R.mul(sample_b[i]);
        p.x += pos.x; p.y += pos.y; p.z += pos.z;
        int ix = (int)((p.x - bmin.x) * inv_res);
        int iy = (int)((p.y - bmin.y) * inv_res);
        int iz = (int)((p.z - bmin.z) * inv_res);
        if (ix >= 0 && ix < s0 && iy >= 0 && iy < s1 && iz >= 0 && iz < s2) {
            if (dist_field[(ix * s1 + iy) * s2 + iz] <= margin) return false;
        }
    }
    for (size_t i = 1; i < sample_b.size(); i += 2) {
        Vec3 p = R.mul(sample_b[i]);
        p.x += pos.x; p.y += pos.y; p.z += pos.z;
        int ix = (int)((p.x - bmin.x) * inv_res);
        int iy = (int)((p.y - bmin.y) * inv_res);
        int iz = (int)((p.z - bmin.z) * inv_res);
        if (ix >= 0 && ix < s0 && iy >= 0 && iy < s1 && iz >= 0 && iz < s2) {
            if (dist_field[(ix * s1 + iy) * s2 + iz] <= margin) return false;
        }
    }
    return true;
}

bool check_segment(const Vec3& p1, const Quat& q1, const Vec3& p2, const Quat& q2, int n_sub = 5) {
    for (int i = 0; i <= n_sub; ++i) {
        float t = (float)i / n_sub;
        Vec3 p = { (1.0f - t)*p1.x + t*p2.x, (1.0f - t)*p1.y + t*p2.y, (1.0f - t)*p1.z + t*p2.z };
        Quat q = slerp(q1, q2, t);
        Mat3 R = quat_to_mat(q);
        if (!check_pose_fast(p, R, 0.005f)) return false;
    }
    return true;
}

int main() {
    FILE* f_hdr = fopen("/app/sdf_header.bin", "rb");
    fread(shape, sizeof(int), 3, f_hdr);
    fread(&bmin, sizeof(float), 3, f_hdr);
    fread(&res, sizeof(float), 1, f_hdr);
    fclose(f_hdr);

    int total_voxels = shape[0] * shape[1] * shape[2];
    dist_field.resize(total_voxels);
    FILE* f_df = fopen("/app/dist_field.raw", "rb");
    fread(dist_field.data(), sizeof(float), total_voxels, f_df);
    fclose(f_df);

    sample_b.resize(3000);
    FILE* f_sb = fopen("/app/sample_b.raw", "rb");
    fread(sample_b.data(), sizeof(float), 3000 * 3, f_sb);
    fclose(f_sb);

    // Read full path points from python-prepared file
    FILE* f_path = fopen("/app/full_raw_path.txt", "r");
    if (!f_path) {
        std::cerr << "Could not open /app/full_raw_path.txt" << std::endl;
        return 1;
    }

    std::vector<Vec3> poses;
    std::vector<Quat> quats;
    std::vector<Mat3> mats;

    Vec3 p;
    float r[9];
    while (fscanf(f_path, "%f %f %f %f %f %f %f %f %f %f %f %f",
                  &p.x, &p.y, &p.z,
                  &r[0], &r[1], &r[2], &r[3], &r[4], &r[5], &r[6], &r[7], &r[8]) == 12) {
        poses.push_back(p);
        Mat3 R;
        for (int i = 0; i < 3; ++i)
            for (int j = 0; j < 3; ++j)
                R.m[i][j] = r[i*3 + j];
        mats.push_back(R);
        quats.push_back(mat_to_quat(R));
    }
    fclose(f_path);

    std::cout << "Loaded " << poses.size() << " raw waypoints." << std::endl;

    // Greedy shortcutting
    // Limits: max linear step = 0.08m, max angular step = 0.16 rad
    std::vector<int> selected = {0};
    int cur = 0;

    while (cur < (int)poses.size() - 1) {
        int best_next = cur + 1;
        for (int nxt = cur + 1; nxt < (int)poses.size(); ++nxt) {
            float dx = poses[nxt].x - poses[cur].x;
            float dy = poses[nxt].y - poses[cur].y;
            float dz = poses[nxt].z - poses[cur].z;
            float dist = sqrtf(dx*dx + dy*dy + dz*dz);

            float d_rot = fabsf(quats[cur].dot(quats[nxt]));
            if (d_rot > 1.0f) d_rot = 1.0f;
            float rot_angle = 2.0f * acosf(d_rot);

            if (dist > 0.08f || rot_angle > 0.16f) break;

            if (check_segment(poses[cur], quats[cur], poses[nxt], quats[nxt], 5)) {
                best_next = nxt;
            } else {
                break;
            }
        }
        selected.push_back(best_next);
        cur = best_next;
    }

    std::cout << "Shortcutting completed: " << selected.size() << " waypoints selected!" << std::endl;

    // Write final actions to file
    // Each line: dx dy dz droll dpitch dyaw (world frame)
    FILE* f_act = fopen("/app/actions.txt", "w");
    for (size_t i = 0; i < selected.size() - 1; ++i) {
        int i1 = selected[i];
        int i2 = selected[i+1];
        Vec3 p1 = poses[i1], p2 = poses[i2];
        Mat3 R1 = mats[i1], R2 = mats[i2];

        float dx = p2.x - p1.x;
        float dy = p2.y - p1.y;
        float dz = p2.z - p1.z;

        // Relative rotation in world frame: R_rel = R2 * R1^T
        Mat3 R_rel;
        for (int r_idx = 0; r_idx < 3; ++r_idx) {
            for (int c_idx = 0; c_idx < 3; ++c_idx) {
                R_rel.m[r_idx][c_idx] = R2.m[r_idx][0]*R1.m[c_idx][0] +
                                        R2.m[r_idx][1]*R1.m[c_idx][1] +
                                        R2.m[r_idx][2]*R1.m[c_idx][2];
            }
        }

        // Convert R_rel to Euler xyz
        // pitch = asin(-R_rel[2][0])
        float pitch = asinf(std::max(-1.0f, std::min(1.0f, -R_rel.m[2][0])));
        float roll = 0.0f, yaw = 0.0f;
        if (cosf(pitch) > 1e-4f) {
            roll = atan2f(R_rel.m[2][1], R_rel.m[2][2]);
            yaw  = atan2f(R_rel.m[1][0], R_rel.m[0][0]);
        }

        fprintf(f_act, "%.6f %.6f %.6f %.6f %.6f %.6f\n", dx, dy, dz, roll, pitch, yaw);
    }
    fclose(f_act);
    std::cout << "Saved " << (selected.size() - 1) << " actions to /app/actions.txt!" << std::endl;

    return 0;
}

