};

uint64_t state_key(int ix, int iy, int iz, int ir, int ip, int iyw) {
    uint64_t k = 0;
    k |= ((uint64_t)(ix + 500) & 0x7FF);
    k |= (((uint64_t)(iy + 500) & 0x7FF) << 11);
    k |= (((uint64_t)(iz + 500) & 0x7FF) << 22);
