    FILE* f_sb = fopen("/app/sample_b.raw", "rb");
    fread(sample_b.data(), sizeof(float), 3000 * 3, f_sb);
    fclose(f_sb);

    // Exact current pose from simulator
    Vec3 p0 = {0.99938f, 1.60676f, 0.46576f};
    float qw = 0.23868f, qx = -0.52160f, qy = -0.81660f, qz = 0.06427f;
    Mat3 R0;
