    R0.m[0][1] = 2.0f*(qx*qy - qw*qz);
    R0.m[0][2] = 2.0f*(qx*qz + qw*qy);
    R0.m[1][0] = 2.0f*(qx*qy + qw*qz);
    R0.m[1][1] = 1.0f - 2.0f*(qx*qx + qz*qz);
    R0.m[1][2] = 2.0f*(qy*qz - qw*qx);
    R0.m[2][0] = 2.0f*(qx*qz - qw*qy);
    R0.m[2][1] = 2.0f*(qy*qz + qw*qx);
    R0.m[2][2] = 1.0f - 2.0f*(qx*qx + qy*qy);

    std::cout << "Starting search from current pose..." << std::endl;

    float step_xyz = 0.015f;
    float step_rot = 0.03f;

    std::vector<State> all_states;
    std::unordered_map<uint64_t, int> visited;

    auto push_state = [&](int ix, int iy, int iz, int ir, int ip, int iyw, int parent) -> int {
        uint64_t k = state_key(ix, iy, iz, ir, ip, iyw);
        if (visited.count(k)) return -1;
