        int cur_idx = top.idx;
        State s = all_states[cur_idx];

        Vec3 pos = {p0.x + s.ix * step_xyz, p0.y + s.iy * step_xyz, p0.z + s.iz * step_xyz};
        Mat3 dR = euler_to_mat(s.ir * step_rot, s.ip * step_rot, s.iyw * step_rot);
        Mat3 R = mul_mat(dR, R0);

        if (pos.y > 1.70f) {
            if (can_slide_to_infinity(pos, R)) {
                std::cout << "SUCCESS! PUZZLE SOLVED AT STATE " << cur_idx 
                          << "! pos=[" << pos.x << ", " << pos.y << ", " << pos.z << "]" << std::endl;
                goal_idx = cur_idx;
                break;
            }
        }

        expanded++;
        if (expanded % 10000 == 0) {
            std::cout << "Expanded " << expanded << ", visited " << visited.size()
                      << ", cur pos=[" << pos.x << ", " << pos.y << ", " << pos.z << "]" << std::endl;
        }

        if (expanded > 100000) {
            std::cout << "Expansion limit reached!" << std::endl;
            break;
        }

        for (const auto& m : moves) {
            int nix = s.ix + m.dx, niy = s.iy + m.dy, niz = s.iz + m.dz;
            int nir = s.ir + m.dr, nip = s.ip + m.dp, niyw = s.iyw + m.dyw;

            uint64_t nk = state_key(nix, niy, niz, nir, nip, niyw);
            if (visited.count(nk)) continue;

            Vec3 npos = {p0.x + nix * step_xyz, p0.y + niy * step_xyz, p0.z + niz * step_xyz};
            Mat3 ndR = euler_to_mat(nir * step_rot, nip * step_rot, niyw * step_rot);
            Mat3 nR = mul_mat(ndR, R0);

            if (get_clearance(npos, nR) > 0.003f) {
                int nidx = push_state(nix, niy, niz, nir, nip, niyw, cur_idx);
                if (nidx >= 0) {
                    pq.push({heuristic(nix, niy, niz), nidx});
                }
            }
        }
    }

    if (goal_idx >= 0) {
        std::vector<State> path;
        int curr = goal_idx;
        while (curr >= 0) {
            path.push_back(all_states[curr]);
            curr = all_states[curr].parent;
        }
        std::reverse(path.begin(), path.end());
        std::cout << "Final escape path length: " << path.size() << " steps!" << std::endl;

        FILE* f_out = fopen("/app/escape_from_here.txt", "w");
        for (const auto& st : path) {
            Vec3 pos = {p0.x + st.ix * step_xyz, p0.y + st.iy * step_xyz, p0.z + st.iz * step_xyz};
            Mat3 dR = euler_to_mat(st.ir * step_rot, st.ip * step_rot, st.iyw * step_rot);
            Mat3 R = mul_mat(dR, R0);
            fprintf(f_out, "%.5f %.5f %.5f %.5f %.5f %.5f %.5f %.5f %.5f %.5f %.5f %.5f\n",
                    pos.x, pos.y, pos.z,
                    R.m[0][0], R.m[0][1], R.m[0][2],
                    R.m[1][0], R.m[1][1], R.m[1][2],
                    R.m[2][0], R.m[2][1], R.m[2][2]);
        }
        fclose(f_out);
        std::cout << "Saved to /app/escape_from_here.txt" << std::endl;
    }

    return 0;
}

